// === Tab: mySketch.js ===
// It is a 3D shader made for the weekly Creative Coding Challenge
// (https://openprocessing.org/curation/78544) on the theme "Survival".
//
// The story is as follows:
//
// In a bleak future where the lines between reality and illusion are blurred,
// robots programmed to crush the world's greatest artists are on the hunt.
// They enjoy capturing them and taking them to the legendary FX Stone.
// 
// The FX Stone, it is said, can give a man new ideas the moment he touches it.
// But in the hands of these machines, it is an instrument of terror.
// At night, when the moon is blood-red in the sky, the machines stalk their
// victims through the dark alleys of the city, where metallic footsteps echo ominously.
// With diabolical laughter, they drag their captives to the FX Stone.
// Something deeply sinister compels them to give the poor souls one last inspiration
// before smashing their skulls against the edge of the stone. 
// Over the course of many decades, a notch has been carved into the stone,
// digging deeper and deeper each time.

let theShader, mouseZ = 0,
		useDpr = false, // true if you feel you have a beefy GPU
		dpr = useDpr ? window.devicePixelRatio : 1, 
		ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;

const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext;
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

function mousePressed() {
	mouseZ = 1;
}

function mouseReleased() {
	mouseZ = 0;
}

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas=document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2407110/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas=document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("u_resolution", [width, height]);
  theShader.setUniform("u_time", millis() / 1000.0);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0), mouseZ]);

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}


// === Tab: vert.glsl ===
#version 300 es 
in vec4 aPosition;
void main() { gl_Position = aPosition*2.-1.; }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/ 
precision highp float;
out vec4 O;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_mouse;
#define mouse vec3(u_mouse.xy/R,u_mouse.z)
#define P (int(u_mouse.z))
#define FC gl_FragCoord.xy
#define R u_resolution
#define T u_time
#define MN min(R.x,R.y)
#define N normalize
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p, vec2 k, mat2 m) {
	float t=.0, a=1., h=.0;
	for (float i=.0; i<6.; i++) {
		t+=a*noise(p+k);
		p=2.*p*m;
		a*=.5;
		h+=a;
	}
	return t/h;
}
float pattern(vec2 uv, float k) {
	float n=3., d=1., col=.0; vec2 f=vec2(0);
	for (float i=.0; i++<n;) {
		d=fbm(uv*d,f,rot(i));
		uv*=k;
		col+=d;
	}
	return col/n;
}
vec3 concrete(vec2 uv) {
	vec3 col=vec3(0);
	uv*=rot(.6);
	col+=mix(.2,.7,pattern((uv+vec2(-5,-7))*6.,4.));
	col-=.2*noise((uv+vec2(-.2,.3))*1.);
	return col;
}
float scratches(vec2 p) {
	return mix(.0,1.,noise(p.xx*120.));
}
vec3 sky(vec2 p) {
	float
	a=fbm(vec2(10.+p.x+T*.005,p.y*3.),vec2(T*.005,0),mat2(1.2,1.,-.5,1.05)),
	b=fbm(vec2(90.+p.x*2.+T*.005,p.y*5.),vec2(T*.01,.0),mat2(1.6,1.2,-.5,1));
	b=S(.25,.7,b);
	return mix(vec3(1),vec3(.1),a*b);
}
float box(vec3 p, vec3 s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z));
}
float disc(vec3 p, vec2 s) {
	vec2 c=vec2(length(p.xy)-s.x, abs(p.z)-s.y);
	return length(max(c,.0))+min(.0,max(c.x,c.y));
}
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float fixes(vec3 p, vec2 s) {
	float d=disc(vec3(abs(p.x)-.65,abs(p.y)-.65,abs(p.z)-1.),s);
	return d;
}
float map(vec3 p) {
	float d=box(vec3(abs(p.x)-1.1,abs(p.y)-1.1,p.z),vec3(1.-.0125*noise(cross(p,p.zxy).zy)))-.025*noise(cross(p,p.yyy).zy);
	d=smin(d,-(length(p-vec3(1.015,2.15,-1.1))-.5+.025*noise(cross(p,-p.zxy).yz*4.)),-.1*fbm(p.xy*12.,vec2(33),rot(.42)));
	d=smin(d,-fixes(vec3(abs(p.x)-1.1,abs(p.y)-1.1,p.z),vec2(.05,.05)),-.04*noise(p.xy*120.));
	return d;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
float occlusion(vec3 p, vec3 n, float dist) {
	return clamp(map(p+n*dist)/dist,.0, 1.);
}
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=N(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i);
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,64.*d/i);
		i+=d;
	}
	return shd;
}
float line(vec2 p, vec2 a, vec2 b, float r) {
  p=p-a, b=b-a;
  return length(p-b*clamp(dot(p,b)/dot(b,b),.0,1.))-r;
}
float chrF(vec2 p, float s) {
	float f=SE(line(p,vec2(-1,1), vec2(.5,1),.0),s);
	f=max(f,SE(line(p,vec2(-1,.125), vec2(0,.125),.0),s));
	f=max(f,SE(line(p,vec2(-1), vec2(-1,1),.0),s));
	return f;
}
float chrX(vec2 p, float s) {
	float x=SE(max(abs(p.x),abs(p.y)),s*2.);
	x=max(x,SE(line(p,vec2(1,-1),vec2(-1,1),.0),s));
	x=max(x,SE(line(p,vec2(-1,-1),vec2(1,1),.0),s));
	return x;
}
void cam(inout vec3 p) {
	if (P>0) {
		p.yz*=rot(-mouse.y*6.2+3.14);
		p.xz*=rot(3.14-mouse.x*6.3);
	} else {
		p.yz*=rot(-.42);
		p.xz*=rot(.42);
	}
}
vec3 scene1(vec2 uv) {
	vec3 col=vec3(0),
	p=vec3(0,0,-7),
	rd=N(vec3(uv,1.2)),
	lp=vec3(-1,2,-4);
	cam(p); cam(rd); cam(lp);
	for (float i=.0; i++<200.;) {
		float d=map(p);
		if (abs(d)<1e-3) {
			vec3 n=norm(p), l=N(lp-p);
			float
			dif=clamp(dot(l,n),.0,1.),
			shd=shadow(p+5e-2*n,lp),
			occ=occlusion(p, n, 12.)*.5+.5,
			ref=pow(clamp(dot(reflect(rd,n),l),.0,1.),32.);
			col+=concrete(p.xy+vec2(-.1,.3)*n.z)*abs(n.z);
			col+=concrete(p.yz+vec2(.2,-.7)*n.x)*abs(n.x);
			col+=concrete(p.xz+vec2(-.7,.4)*n.y)*abs(n.y);
			if (n.z<-.1) {
				float k=mix(.02,.8,noise(p.xy*5.)), s=.1,
				ft=k*chrF((p.xy-vec2(-.9,1)*(1.-k*.01))*2.,s),
				xt=k*chrX((p.xy-vec2(1.1,-1.1)*(1.-k*.025))*2.,s);
				col-=ft-ref*ft*.8;
				col-=xt-ref*xt*.8;
				float b=mix(.05,.45,noise(p.xx*13.))*SE(max(abs(p.x-1.075),abs(p.y+.122)-1.8),.4+.02*noise(p.xy*32.));
				col-=mix(.2,.7,S(.0,1.,p.y))*noise((p.xy-vec2(1,.8))*.5);
				col-=b;
				col=mix(col,vec3(.8,.05,.01),mix(.0,1.,b))+ref*b*.6;
			}
			float e=mix(.0,.2,noise((p.xy*rot(.78)).xx));
			col+=.5*e*scratches(.25*(p.xy*rot(1.5707+noise(p.yz+floor(p.yz*.5+.5))*.05)));
			col+=.2*e*SE(mod(1.75+p.y*2.,2.)-1.,.01);
			col*=.2+.8*dif*shd+ref*.2;
			col*=occ;
			break;
		}
		if (d>7.) {
			col=mix(vec3(.1),vec3(1),max(sky(uv),.01));
			break;
		}
		p+=rd*d;
	}
	return col;
}
float rect(vec2 p, float s) {
	p=abs(p)-(s-.0125);
	return length(max(p,.0))+min(.0,max(p.x,p.y));
}
float logo(vec2 p) {
	float
	k=.05,
	s=.125,
	a=rect(p-vec2(s,3.*s),s),
	b=rect(p-vec2(-s,s),s),
	c=rect(p+vec2(s,3.*s),s),
	d=rect(p+vec2(-s,s),s);
	return smin(smin(a,b,k),smin(c,d,k),k);
}
float logoanimation(vec2 p) {
	float
	n=4.,
	f=mod(T,n),
	t=pow(f>(n-1.)?n-f:f,7.),
	v=fract(t),
	scene=floor(mod(f,n)),
	k=.05,
	s=.125;
	vec2 q=vec2(-s,s);
	if (scene==1.) {
		if (f>1.5) q.x-=max(-s*2.,1.5-f);
	} else if (scene==2.) {
		q.x-=-s*2.;
		q.y+=max(-s*2.,2.-f);
	}
	float
	a=rect(p-mix(vec2(s,3.*s),q,t>1.?1.:v),s),
	b=rect(p-q,s),
	c=rect(p+mix(vec2(s,3.*s),q,t>1.?1.:v),s),
	d=rect(p+q,s);
	return mix(
		smin(smin(a,b,k),smin(c,d,k),k),
		smin(b,d,k),
		t>1.?1.:fract(t*t)
	);
}
#define L(uv) (vec3(1)*SE(logoanimation(uv*2.5),.0125))
float easeInOutQuad(float t) {
	if ((t*=2.)<1.) return .5*t*t;
	else return -.5*((t-1.)*(t-3.)-1.);
}
#define W easeInOutQuad
float placeLogo() {
	vec2 p=FC/R;
	p*=vec2(R.x/R.y,1);
	p-=vec2(R.x/R.y,0);
	p+=vec2(.05,-.075);
	return SE(logo(p*12.),.01);
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0);
	float prog=T*.125,
	scene=floor(prog);
	if (scene==.0) {
		col=mix(vec3(0),L(uv),W(S(.0,1.,prog)));
	}
	if (scene>=1.&&scene<2.) {
		col=mix(L(uv),vec3(0),W(S(1.,2.,prog)));
	}
	if (scene>=2.) {
		col=mix(vec3(0),scene1(uv)+placeLogo(),(S(2.,2.1,prog)));
	}
	O=vec4(col,1);
}

